class Component extends DCLogic {
  state = { open: false, i: 0, gi: null, ii: 0, slide: {} };
  componentDidMount() {
    document.documentElement.lang = 'en-US';
    this.syncHead();
  }
  componentDidUpdate() { this.syncHead(); }
  syncHead() {
    const P = window.AHV_GALLERY_RENDER, R = P && P.resolveRoute(this.props.route);
    if (!R) return;
    if (this._head !== R.path) { P.applyHead(R); this._head = R.path; }
    // The pair's <helmet> <title> can be reasserted after mount, so the governed title is kept in sync here.
    if (document.title !== R.metadata.title) document.title = R.metadata.title;
  }
  componentWillUnmount() { document.body.style.overflow = ''; }
  openAt(idx) {
    this.setState({ open: true, i: idx });
    document.body.style.overflow = 'hidden';
    setTimeout(() => { const c = document.getElementById('gallery-close'); if (c) c.focus(); }, 30);
  }
  // Eight-route viewer: opens a specific group's image, restores focus to the originating thumbnail.
  openGroupAt(gi, ii) {
    // Remember where the viewer was opened from, so closing returns focus to that thumbnail
    // even after Previous/Next has moved to a different image.
    this._openedFrom = 'g' + gi + '-i' + ii;
    this.setState({ gi: gi, ii: ii });
    document.body.style.overflow = 'hidden';
    setTimeout(() => { const c = document.getElementById('gallery-close'); if (c) c.focus(); }, 30);
  }
  closeGroupViewer() {
    const key = this._openedFrom || ('g' + this.state.gi + '-i' + this.state.ii);
    this.setState({ gi: null });
    document.body.style.overflow = '';
    setTimeout(() => {
      // Focus returns to the control the image was opened from. A slider only renders its current slide, so if
      // that control is no longer displayed the group's visible control takes focus instead — focus is never lost.
      const gi = key.split('-')[0];
      const b = document.querySelector('button[data-gallery-index="' + key + '"]');
      const visible = (el) => !!(el && el.getClientRects().length);
      const target = visible(b) ? b : [...document.querySelectorAll('button[data-gallery-index^="' + gi + '-"]')].find(visible);
      if (target) target.focus();
    }, 30);
  }
  goGroup(d) {
    const D = window.AHV_GALLERY_FAMILY, P = window.AHV_GALLERY_RENDER;
    const R = P && P.resolveRoute(this.props.route); if (!R || this.state.gi == null) return;
    const n = R.groups[this.state.gi].count;
    this.setState(s => ({ ii: (s.ii + d + n) % n }));
  }
  closeViewer() {
    const idx = this.state.i;
    this.setState({ open: false });
    document.body.style.overflow = '';
    setTimeout(() => { const btn = document.querySelector('button[data-gallery-index="' + idx + '"]'); if (btn) btn.focus(); }, 30);
  }
  renderVals() {
    const GP = window.AHV_GALLERY_RENDER;
    const GR = GP ? GP.resolveRoute(this.props.route) : null;
    if (GR) {
      const guard = () => {}; /* preview-only navigation guard neutralised for the published site: all 91 anchors it is bound to carry real destinations */
      const api = {
        open: (gi, ii) => this.openGroupAt(gi, ii),
        slide: (gi, i) => this.setState(s => ({ slide: Object.assign({}, s.slide, { [gi]: i }) }))
      };
      const V = GP.galleryVals(GR, this.state, api, guard);
      const hi = GR.heroImage;
      return Object.assign({ guard, isAyurveda: false,
        // React node, not a raw interpolated src: the source hero renders at decoded original proportions.
        heroEl: hi ? React.createElement('img', { src: hi.src, alt: hi.alt || '', width: hi.width, height: hi.height,
          'data-source-pointer': hi.ptr, style: { width: '100%', maxWidth: hi.width + 'px', height: 'auto', display: 'block' } }) : null,
        gallery: [], footerLinks: [],
        close: () => this.closeGroupViewer(), prev: () => this.goGroup(-1), next: () => this.goGroup(1),
        dlgKey: (e) => {
          if (e.key === 'Escape') { e.preventDefault(); this.closeGroupViewer(); return; }
          if (e.key === 'ArrowLeft') { e.preventDefault(); this.goGroup(-1); return; }
          if (e.key === 'ArrowRight') { e.preventDefault(); this.goGroup(1); return; }
          if (e.key === 'Tab') {
            const f = [...e.currentTarget.querySelectorAll('button')];
            const first = f[0], last = f[f.length - 1];
            if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
            else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
          }
        },
        // React node, not a raw interpolated src: the browser prefetches an uninterpolated src attribute and
        // 404s on the literal placeholder URL even when the element is gated behind the open state.
        expandedEl: V.dlgOpen ? React.createElement('img', { id: 'gallery-expanded', src: V.cur.image, alt: V.cur.alt || '',
          width: V.cur.width, height: V.cur.height, style: { display: 'block', width: 'auto', height: 'auto', maxWidth: 'min(1280px,100%)', maxHeight: 'calc(100vh - 220px)', objectFit: 'contain', margin: '20px 0', borderRadius: '4px', background: '#000' } }) : null
      }, V);
    }
    const D = window.AHV_AYURVEDA_GALLERY || { gallery: [], footerLinks: [] };
    const A = 'https://ayurvedichealingvillage.com';
    const n = D.gallery.length, i = this.state.i;
    const cur = D.gallery[i] || { image: '', alt: '', width: 1280, height: 572 };
    const go = (d) => this.setState(s => ({ i: (s.i + d + n) % n }));
    return {
      guard: () => {} /* preview-only nav guard neutralised for the published site */, isAyurveda: true, hasGallery: false,
      gallery: D.gallery.map((g, idx) => ({ ...g, i: idx, open: () => this.openAt(idx) })),
      footerLinks: D.footerLinks.map(f => ({ ...f, url: A + f.href })),
      dlgDisplay: this.state.open ? 'flex' : 'none', dlgOpen: this.state.open,
      // Same lazy-node pattern for the approved Ayurveda viewer: identical rendered attributes, no literal-template request.
      expandedEl: this.state.open ? React.createElement('img', { id: 'gallery-expanded', src: cur.image, alt: cur.alt || '',
        width: cur.width, height: cur.height, style: { display: 'block', width: 'auto', height: 'auto', maxWidth: 'min(1280px,100%)', maxHeight: 'calc(100vh - 220px)', objectFit: 'contain', margin: '20px 0', borderRadius: '4px', background: '#000' } }) : null,
      cur, counter: n ? (i + 1) + ' of ' + n : '',
      close: () => this.closeViewer(),
      prev: () => go(-1), next: () => go(1),
      dlgKey: (e) => {
        if (e.key === 'Escape') { e.preventDefault(); this.closeViewer(); return; }
        if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); return; }
        if (e.key === 'ArrowRight') { e.preventDefault(); go(1); return; }
        if (e.key === 'Tab') {
          const f = [...e.currentTarget.querySelectorAll('button')];
          const first = f[0], last = f[f.length - 1];
          if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
          else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        }
      }
    };
  }
}
